(6, 1, '2023-01-04 07:43:46', '2023-01-04 07:43:46', 'footer#main-footer > .container {\r\n    display: none;\r\n}\r\ndiv#footer-bottom {\r\n    background: #f7f7f7;\r\n    padding: 20px 0 6px;\r\n}\r\n.page-id-5352 header {\r\n	display:none;\r\n}\r\nul.et_pb_tabs_controls {\r\n    background-color: unset;\r\n}\r\n.tabdes img {\r\n	    width: 17%;\r\n    margin: 1%;\r\n}\r\n.inq_now_form .wpcf7-not-valid-tip {\r\n    color: #ffffff;\r\n}\r\n.quick-links a {\r\n	color:#000;\r\n	line-height: 1.9;\r\n}\r\n.inq_now_form input {\r\n	font-weight: 600;\r\n    font-size: 16px;\r\n    padding: 14px !important;\r\n    border-radius: 4px;\r\n    color: #000 !important;\r\n}\r\n.inq_now_form select {\r\n	font-weight: 600;\r\n    font-size: 16px;\r\n    padding: 14px !important;\r\n    border-radius: 4px;\r\n    color: #686868 !important;\r\n}\r\n.inq_now_form textarea {\r\n	font-weight: 600;\r\n    font-size: 16px;\r\n    padding: 14px !important;\r\n    border-radius: 4px;\r\n    color: #000 !important;\r\n	height:65px;\r\n}\r\n.inq_now_form .wpcf7-submit {\r\n 	 padding: 9px;\r\n    border: none;\r\n    background: #ffa4b6!important;\r\n    color: #000!important;\r\n    width: 100%;\r\n    font-size: 19px;\r\n    font-weight: 600;\r\n    cursor: pointer;\r\n}\r\n.pum-container input {\r\n    background-color: #e3e3e3 !important;\r\n    font-size: 16px;\r\n	color:#000;\r\n	padding: 15px !important;\r\n}\r\n.pum-container .wpcf7-submit {\r\n    background-color: #e11f23 !important;\r\n    font-size: 18px;\r\n	color:#ffffff;\r\n	width: 150px;\r\n	cursor:pointer;\r\n}\r\n.et_pb_tabs_controls li {\r\n    border-right: 5px solid #e02b20;\r\n}\r\n\r\n@media (max-width: 480px) {\r\nbody {\r\n    overflow-x: hidden !important;\r\n}\r\n	.tabdes img {\r\n    width: 30%;\r\n    margin: 1%;\r\n}\r\n	.et_pb_tabs_controls li {\r\n    border-right: 2px solid #e02b20;\r\n}\r\n	.et_pb_tabs_controls li a {\r\n    padding: 4px 7px;\r\n}\r\n	.et_pb_tabs_controls li {\r\n    float: left;\r\n}\r\n}\r\n@media (min-width: 992px) {\r\n	a.from-btn-float{\r\n		display: none !important;\r\n	}\r\n	.mystickyelements-fixed {\r\n    display: none;\r\n}\r\n}\r\n\r\na.from-btn-float {\r\n    position: fixed;\r\n    bottom: 10px;\r\n    z-index: 9999;\r\n    padding: 5px 12px;\r\n    background: #e11f23;\r\n    font-family: \'PT Sans\';\r\n    left: 0;\r\n    color: #fff;\r\n	display:none;\r\n}\r\n.mystickyelements-fixed {\r\n\r\n    top: 80% !important;\r\n}\r\n\r\ninput.text, input.title, input[type=email], input[type=password], input[type=tel], input[type=text], select, textarea {\r\n    background-color: #f8f8f8;\r\n    border: 1px solid #bbb;\r\n    padding: 2px;\r\n    color: #4e4e4e;\r\n    display: block;\r\n    width: 100%;\r\n    padding: 9px;\r\n    margin-top: 3px;\r\n    border: none;\r\n}\r\ninput.wpcf7-form-control.has-spinner.wpcf7-submit {\r\n    padding: 9px;\r\n    border: none;\r\n    background: #e11f23;\r\n    color: #fff;\r\n}\r\n.paoc-popup-margin.paoc-cus-close-txt {\r\n    display: none;\r\n}\r\n.paoc-popup-margin.paoc-popup-snote {\r\n    display: none;\r\n}\r\n.paoc-credit-wrp {\r\n    display: none;\r\n}\r\na.paoc-popup-click.paoc-popup-cust-4652.paoc-popup-simple_link.paoc-popup-link {\r\n    background: white;\r\n    padding: 13px 20px;\r\n    text-align: center;\r\n    font-family: \'PT Sans\';\r\n    color: #000;\r\n    font-weight: 600;\r\n    font-size: 17px;\r\n}\r\n\r\nbody, html {\r\n    overflow-x: hidden !important;\r\n}\r\n\r\n.paoc-popup-mheading {\r\n    font-size: 21px;\r\n    color: #000000;\r\n    line-height: normal;\r\n    font-weight: 700;\r\n}', 'Divi', '', 'publish', 'closed', 'closed', '', 'divi', '', '', '2023-06-15 05:54:43', '2023-06-15 05:54:43', '', 0, 'https://virgolam.com/laminate-sheets/2023/01/04/divi/', 0, 'custom_css', '', 0),
