nd_color=\"#e11f23\" background_enable_pattern_style=\"on\" background_pattern_style=\"squares\" background_pattern_color=\"rgba(0,0,0,0.07)\" custom_padding=\"20px||20px||true|false\" custom_padding_tablet=\"20px||20px||true|false\" custom_padding_phone=\"0px||0px||true|false\" box_shadow_style=\"preset1\" global_colors_info=\"{}\"][et_pb_row column_structure=\"3_4,1_4\" _builder_version=\"4.19.4\" _module_preset=\"default\" width=\"90%\" max_width=\"90%\" global_colors_info=\"{}\"][et_pb_column type=\"3_4\" _builder_version=\"4.19.4\" _module_preset=\"default\" global_colors_info=\"{}\"][et_pb_text _builder_version=\"4.19.4\" _module_preset=\"default\" text_font=\"PT Sans||||||||\" text_text_color=\"#FFFFFF\" text_font_size=\"20px\" text_line_height=\"1.3em\" text_font_size_tablet=\"24px\" text_font_size_phone=\"17px\" text_font_size_last_edited=\"on|phone\" global_colors_info=\"{}\"]<p>Premium Quality laminates by Virgo are made from different layers of impregnated decorative papers and kraft papers acted upon by heat and high pressure. They are pure Phenolic/Melamine with uniform and superior sanding, ensuring the best bonding with substrates.</p>[/et_pb_text][/et_pb_column][et_pb_column type=\"1_4\" _builder_version=\"4.19.4\" _module_preset=\"default\" global_colors_info=\"{}\"][et_pb_text module_class=\"popmake-4901\" _builder_version=\"4.19.4\" _module_preset=\"default\" text_font=\"Quicksand|600|||||||\" text_text_color=\"#E02B20\" text_font_size=\"18px\" background_color=\"#FFFFFF\" text_orientation=\"center\" custom_padding=\"15px||15px||true|false\" border_radii=\"on|5px|5px|5px|5px\" global_colors_info=\"{}\"]<p>Download Catalogue</p>[/et_pb_text][/et_pb_column][/et_pb_row][/et_pb_section][et_pb_section fb_built=\"1\" _builder_version=\"4.19.4\" _module_preset=\"default\" background_color=\"#f2f2f2\" custom_padding=\"||0px||false|false\" global_colors_info=\"{}\"][et_pb_row column_structure=\"1_4,1_4,1_4,1_4\" use_custom_gutter=\"on\" gutter_width=\"2\" _builder_version=\"4.19.4\" _module_preset=\"default\" width=\"90%\" max_width=\"90%\" global_colors_info=\"{}\"][et_pb_column type=\"1_4\" _builder_version=\"4.19.4\" _module_preset=\"default\" global_colors_info=\"{}\"][et_pb_blurb title=\"About Us\" icon_placement=\"left\" _builder_version=\"4.19.4\" _module_preset=\"default\" header_font=\"Montserrat|600|||||||\" header_text_color=\"#000000\" body_font=\"Quicksand||||||||\" body_text_color=\"#000000\" body_font_size=\"15px\" custom_padding_tablet=\"\" custom_padding_phone=\"||15px||false|false\" custom_padding_last_edited=\"on|phone\" border_width_bottom_tablet=\"\" border_width_bottom_phone=\"1px\" border_width_bottom_last_edited=\"on|phone\" border_color_bottom_tablet=\"\" border_color_bottom_phone=\"rgba(0,0,0,0.25)\" border_color_bottom_last_edited=\"on|phone\" border_style_bottom_tablet=\"\" border_style_bottom_phone=\"dashed\" border_style_bottom_last_edited=\"on|phone\" locked=\"off\" global_colors_info=\"{}\"]<p>The Virgo Group of Companies is dedicated to excelling in what it does - creating high-quality laminates with exceptional designs and finishes loved by architects and homeowners alike. With its Environment-Friendly initiatives, which include the elimination of the use of tropical woods and harmful, ozone-damaging chemicals, Virgo Laminates has Extraordinary written all over it.</p>[/et_pb_blurb][/et_pb_column][et_pb_column type=\"1_4\" _builder_version=\"4.19.4\" _module_preset=\"default\" global_colors_info=\"{}\"][et_pb_blurb title=\"Quick Links\" icon_placement=\"left\" module_class=\"quick-links\" _builder_version=\"4.19.4\" _module_preset=\"default\" header_font=\"Montserrat|600|||||||\" header_text_color=\"#000000\" body_font=\"Quicksand||||||||\" body_text_color=\"#000000\" body_font_size=\"16px\" custom_padding_tablet=\"\" custom_padding_phone=\"||15px||false|false\" custom_padding_last_edited=\"on|phone\" border_width_bottom_tablet=\"\" border_width_bottom_phone=\"1px\" border_width_bot