(4754, 1, '2023-05-29 12:48:59', '2023-05-29 12:48:59', '[text* your-name autocomplete:name placeholder \"Enter Your Name*\"]\r\n\r\n    [email* your-email autocomplete:email placeholder \"Enter Your Email\"] \r\n\r\n    [text* your-mobile placeholder \"Enter Your Mobile\"] \r\n\r\n[select* menu-69 first_as_label \"Who are You?\" \"Architecture\" \"Interior Designers\" \"Carpenters\" \"Construction and Building Companies\" \"Furniture Manufacturers\" \"Retailers\" \"Dealer and Distributor\" \"Others\"]\r\n\r\n    [text* your-state placeholder \"Enter Your State\"]\r\n\r\n    [text* your-city placeholder \"Enter Your City\"]\r\n\r\n    [textarea your-message placeholder \"Enter Your Message\"] \r\n\r\n[submit \"Submit\"]\n1\n[_site_title] Inquiry for Virgo Laminate\n[_site_title] <admin@virgolam.com>\nseo@virgoasia.com, exnovationad@gmail.com\nFrom: [your-name] <[your-email]>\r\nSubject: Inquiry for Virgo Laminate\r\n\r\nName:[your-name]\r\nMobile:[your-mobile]\r\nEmail:[your-email]\r\nDesignation:[menu-69]\r\nState:[your-state]\r\nCity:[your-city]\r\nMessage:[your-message]\r\n\r\n-- \r\nThis e-mail was sent from a contact form on [_site_title] ([_site_url])\nReply-To: [your-email]\n\n\n\n\n[_site_title] \"[your-subject]\"\n[_site_title] <admin@virgolam.com>\n[your-email]\nMessage Body:\r\n[your-message]\r\n\r\n-- \r\nThis e-mail was sent from a contact form on [_site_title] ([_site_url])\nReply-To: [_site_admin_email]\n\n\n\nThank you for your message. It has been sent.\nThere was an error trying to send your message. Please try again later.\nOne or more fields have an error. Please check and try again.\nThere was an error trying to send your message. Please try again later.\nYou must accept the terms and conditions before sending your message.\nPlease fill out this field.\nThis field has a too long input.\nThis field has a too short input.\nThere was an unknown error uploading the file.\nYou are not allowed to upload files of this type.\nThe uploaded file is too large.\nThere was an error uploading the file.\nPlease enter an email address.\nPlease enter a URL.\nPlease enter a telephone number.\nPlease enter a date in YYYY-MM-DD format.\nThis field has a too early date.\nThis field has a too late date.\nPlease enter a number.\nThis field has a too small number.\nThis field has a too large number.\nThe answer to the quiz is incorrect.', 'Landing Page Form', '', 'publish', 'closed', 'closed', '', 'landing-page-form', '', '', '2023-06-15 07:21:09', '2023-06-15 07:21:09', '', 0, 'https://virgolam.com/laminate-sheets/?post_type=wpcf7_contact_form&#038;p=4754', 0, 'wpcf7_contact_form', '', 0),
